files['src/pages/manager/ServiceDeskPage.jsx']=r'''import {useState} from 'react';
import {useParams} from 'react-router-dom';
import {useManagerData,updateMaintenance,updateSupport,resourceName,customerName,managerDemoEnabled} from '@/lib/managerDemoStore';
import {managerPermissions,supportCategories} from '@/mocks/managerData';
import {Screen,Panel,Table,OpenLink,Status,Filters,Field,Select,Input,Details,Textarea,Button,Timeline,Message,NotFound,useAction} from '@/components/manager/ManagerUI';
function DeskDetail({row,data,maintenance}){const [status,setStatus]=useState(row.status),[staffId,setStaff]=useState(row.staffId||''),[notes,setNotes]=useState(row.notes||''),[response,setResponse]=useState(''),action=useAction();const staff=data.staff.filter(s=>s.types.includes(maintenance?'MAINTENANCE':'SUPPORT')),closed=row.status==='RESOLVED';return <><div className="grid gap-6 lg:grid-cols-2"><Panel title={maintenance?'Maintenance issue':'Support ticket'}><Details values={[["ID",row.id],['Issue / subject',maintenance?row.issue:row.subject],...(maintenance?[['Resource type',row.resourceType],['Resource',resourceName(data,row.resourceType,row.resourceId)],['Priority',<Status value={row.priority}/>]]:[['Customer',<OpenLink to={`/manager/customers/${row.customerId}`}>{customerName(data,row.customerId)}</OpenLink>],['Category',row.category]]),['Status',<Status value={row.status}/>],['Assigned staff',data.staff.find(s=>s.id===row.staffId)?.name||'Unassigned'],['Notes',row.notes||'No notes yet']]}/></Panel><Panel title={maintenance?'Issue assignment & updates':'Assignment & resolution'}><form className="space-y-4" onSubmit={e=>{e.preventDefault();if(action.run(()=>maintenance?updateMaintenance(row.id,status,staffId,notes):updateSupport(row.id,{status,staffId,response,notes})))setResponse('');}}><Field label="Assigned staff"><Select label="Desk assigned staff" value={staffId} onChange={setStaff} disabled={closed} options={[["","Unassigned"],...staff.map(s=>[s.id,s.name])]}/></Field><Field label="Status"><Select label="Desk status" value={status} onChange={setStatus} disabled={closed} options={['OPEN','IN_PROGRESS','RESOLVED']}/></Field>{!maintenance&&<Field label="Response to customer"><Textarea aria-label="Response to customer" value={response} onChange={e=>setResponse(e.target.value)} disabled={closed}/></Field>}<Field label={maintenance?'Operational notes':'Resolution notes'} hint={maintenance?'Issue closure records do not automatically release the resource. Verify resource availability separately.':'Required when resolving the ticket. Responses are recorded locally and are not sent.'}><Textarea aria-label={maintenance?'Maintenance notes':'Resolution notes'} required={maintenance||status==='RESOLVED'} value={notes} onChange={e=>setNotes(e.target.value)} disabled={closed}/></Field><Message {...action}/><Button disabled={closed||!managerDemoEnabled||!managerPermissions[maintenance?'manageMaintenance':'manageSupport']}>Save {maintenance?'issue':'ticket'} update</Button>{closed&&<p className="text-xs text-slate-500">This record is resolved.</p>}</form></Panel></div>{!maintenance&&<Panel title="Conversation"><div className="space-y-4">{row.messages.map((message,i)=><div key={i} className="rounded-xl bg-[#f1f6ef] p-4"><div className="flex flex-wrap justify-between gap-2 text-xs"><b>{message.author}</b><span className="text-slate-500">{new Date(message.at).toLocaleString('en-GB')}</span></div><p className="mt-3 whitespace-pre-wrap text-sm leading-6">{message.text}</p></div>)}</div></Panel>}<Panel title="Status timeline"><Timeline entries={row.timeline}/></Panel></>;}
export default function ServiceDeskPage({kind}){const maintenance=kind==='maintenance',data=useManagerData(),{id}=useParams(),[status,setStatus]=useState(''),[category,setCategory]=useState(''),[search,setSearch]=useState('');const collection=maintenance?'maintenance':'support',row=data[collection].find(r=>r.id===id),title=maintenance?'Maintenance':'Support management';if(id&&!row)return <Screen title={title} code={maintenance?'P031':'P038'}><NotFound/></Screen>;const rows=data[collection].filter(r=>(!status||r.status===status)&&(!category||(maintenance?r.resourceType:r.category)===category)&&(!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase())));return <Screen title={id?`${row.id} · ${maintenance?'Maintenance':'Support'}`:title} code={maintenance?'P031':'P038'} description={maintenance?'Track issues for private units, zones, racks and shelves at this facility.':'Assign, respond to and resolve customer requests for your facility.'} action={id&&<OpenLink to={`/manager/${collection}`}>All {collection}</OpenLink>}>{id?<DeskDetail key={id} row={row} data={data} maintenance={maintenance}/>:<Panel title={maintenance?'Facility maintenance issues':'Customer support tickets'}><Filters><Field label="Status"><Select label="Desk filter status" value={status} onChange={setStatus} options={[["","All statuses"],'OPEN','IN_PROGRESS','RESOLVED']}/></Field><Field label={maintenance?'Resource type':'Category'}><Select label="Desk category" value={category} onChange={setCategory} options={[["","All categories"],...(maintenance?['Storage Unit','Zone','Rack','Shelf']:supportCategories)]}/></Field><Field label="Search"><Input aria-label="Desk search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="ID, subject or issue"/></Field></Filters><Table rows={rows} columns={[{key:'id',label:'ID',render:r=><OpenLink to={`/manager/${collection}/${r.id}`}>{r.id}</OpenLink>},{key:'issue',label:maintenance?'Issue':'Subject',render:r=>maintenance?r.issue:r.subject},{key:'resource',label:maintenance?'Resource':'Customer',render:r=>maintenance?`${r.resourceType} · ${resourceName(data,r.resourceType,r.resourceId)}`:customerName(data,r.customerId)},{key:'priority',label:maintenance?'Priority':'Category',render:r=>maintenance?<Status value={r.priority}/>:r.category},{key:'status',label:'Status',render:r=><Status value={r.status}/>},{key:'staff',label:'Assigned staff',render:r=>data.staff.find(s=>s.id===r.staffId)?.name||'Unassigned'}]}/></Panel>}</Screen>;}
'''
files['src/pages/manager/FinancePage.jsx']=r'''import {useState} from 'react';
import {useParams} from 'react-router-dom';
import {useManagerData,refundQuote,decide,money,customerName} from '@/lib/managerDemoStore';
import {managerPermissions} from '@/mocks/managerData';
import {Screen,Panel,Filters,Field,Select,Table,OpenLink,Status,Details,Decision,Timeline,NotFound} from '@/components/manager/ManagerUI';
export default function FinancePage({kind}){const data=useManagerData(),{id}=useParams(),[status,setStatus]=useState(''),refunds=kind==='refunds';const rows=data[kind].filter(r=>!status||r.status===status);if(id){const row=data.refunds.find(r=>r.id===id);if(!row)return <Screen title="Refund" code="P043"><NotFound/></Screen>;const payment=data.payments.find(p=>p.id===row.paymentId);return <Screen title={`Refund ${row.id}`} code="P043" description="Review the original payment and policy calculation before deciding." action={<OpenLink to="/manager/refunds">All refunds</OpenLink>}><div className="grid gap-6 lg:grid-cols-2"><Panel title="Refund calculation"><Details values={[["Customer",customerName(data,row.customerId)],['Original payment',payment?.id],['Original amount',money(payment?.amount)],['Original payment status',<Status value={payment?.status}/>],['Payment date',payment?.date],['Payment method',payment?.method],['Reason',row.reason],['Unused period',`${row.unusedDays} / ${row.periodDays} days`],['Calculated refund',money(row.calculatedRefund??refundQuote(data,row))],['Applicable policy',row.policy],['Approval state',<Status value={row.status}/>]]}/></Panel><Panel title="Manager review" subtitle="Approval records a demo decision; it does not process a payout or mark the original payment as refunded."><Decision status={row.status} available={payment?.status==='PAID'} allowed={managerPermissions.approveRefunds} onDecision={(decision,reason)=>decide('refunds',row.id,decision,reason)}/></Panel></div><Panel title="Refund timeline"><Timeline entries={row.timeline}/></Panel></Screen>;}
return <Screen title={refunds?'Refunds':'Extra charges'} code={refunds?'P043':'P064'} description={refunds?'Review policy-based refund requests for facility payments.':'Additional rental charges and handling fees, with their calculation references.'}><Panel title={refunds?'Refund review queue':'Charge ledger'}><Filters><Field label="Status"><Select label="Finance status" value={status} onChange={setStatus} options={[["","All statuses"],...(refunds?['PENDING','APPROVED','REJECTED']:['PENDING','PAID','CANCELLED'])]}/></Field></Filters><Table rows={rows} columns={[{key:'id',label:refunds?'Refund ID':'Charge ID',render:r=>refunds?<OpenLink to={`/manager/refunds/${r.id}`}>{r.id}</OpenLink>:r.id},{key:'customer',label:'Customer',render:r=>customerName(data,r.customerId)},{key:'reason',label:'Reason'},{key:'paymentId',label:refunds?'Original payment':'Rental',render:r=>refunds?r.paymentId:r.rentalId},{key:'amount',label:refunds?'Calculated refund':'Amount',render:r=>money(refunds?r.calculatedRefund??refundQuote(data,r):r.amount)},{key:'policy',label:'Policy / calculation'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></Screen>;}
'''
files['src/pages/manager/ReportsPage.jsx']=r'''import {useState} from 'react';
import {useManagerData,money,capacity,customerName,unitCode} from '@/lib/managerDemoStore';
import {Screen,Panel,Filters,Field,Input,Select,Table,Status,Meter,Details,ExportButton,Timeline} from '@/components/manager/ManagerUI';
const titleMap={revenue:['Revenue report','P047'],utilization:['Utilization report','P048'],rentals:['Rental history report','P049']};
export default function ReportsPage({kind}){const data=useManagerData(),[from,setFrom]=useState(''),[to,setTo]=useState(''),[status,setStatus]=useState(''),[customer,setCustomer]=useState('');const [title,code]=titleMap[kind],invalid=from&&to&&from>to,c=capacity(data);const payments=data.payments.filter(r=>!invalid&&(!from||r.date>=from)&&(!to||r.date<=to)&&(!status||r.status===status));const paid=payments.filter(r=>r.status==='PAID'),paidTotal=paid.reduce((s,r)=>s+r.amount,0),due=payments.filter(r=>r.status==='PENDING').reduce((s,r)=>s+r.amount,0);const charges=data.charges.filter(r=>r.status==='PAID'&&(!from||r.date>=from)&&(!to||r.date<=to)&&!invalid);const rentals=data.rentals.filter(r=>!invalid&&(!from||r.end>=from)&&(!to||r.start<=to)&&(!status||r.status===status)&&(!customer||r.customerId===customer));return <Screen title={title} code={code} description="Facility-scoped summaries from the local demo ledger. Exports require an authenticated Manager API." action={<ExportButton/>}>{kind!=='utilization'&&<Panel title="Report filters"><Filters><Field label="Period from"><Input aria-label="Report period from" type="date" value={from} onChange={e=>setFrom(e.target.value)}/></Field><Field label="Period to"><Input aria-label="Report period to" type="date" min={from||undefined} value={to} onChange={e=>setTo(e.target.value)}/></Field><Field label={kind==='revenue'?'Payment status':'Rental status'}><Select label="Report status" value={status} onChange={setStatus} options={[["","All statuses"],...(kind==='revenue'?['PAID','PENDING','FAILED']:['ACTIVE','OVERDUE','COMPLETED'])]}/></Field>{kind==='rentals'&&<Field label="Customer"><Select label="Report customer" value={customer} onChange={setCustomer} options={[["","All customers"],...data.customers.map(r=>[r.id,r.name])]}/></Field>}</Filters>{invalid&&<p role="alert" className="text-sm text-red-700">The period end must be on or after its start.</p>}</Panel>}{kind==='revenue'&&<><div className="grid gap-5 sm:grid-cols-3"><Panel title="Collected rental revenue"><p className="text-2xl font-bold">{money(paidTotal)}</p><p className="mt-2 text-xs text-slate-500">{paid.length} paid rental payments in selected period</p></Panel><Panel title="Outstanding invoices"><p className="text-2xl font-bold">{money(due)}</p><p className="mt-2 text-xs text-slate-500">Pending payment amount</p></Panel><Panel title="Collected extra charges"><p className="text-2xl font-bold">{money(status&&status!=='PAID'?0:charges.reduce((s,r)=>s+r.amount,0))}</p><p className="mt-2 text-xs text-slate-500">Shown separately from rental payments</p></Panel></div><Panel title="Revenue by payment method"><div className="manager-chart">{[...new Set(payments.map(p=>p.method))].map(method=>{const amount=paid.filter(p=>p.method===method).reduce((s,r)=>s+r.amount,0);return <div className="manager-chart-row" key={method}><b>{method}</b><div className="manager-chart-track"><div style={{width:`${paidTotal?amount/paidTotal*100:0}%`}}/></div><span className="text-right">{money(amount)}</span></div>;})}{!payments.length&&<p className="text-sm text-slate-500">No payments in this period.</p>}</div></Panel><Panel title="Payment ledger"><Table rows={payments} columns={[{key:'id',label:'Payment ID'},{key:'customer',label:'Customer',render:r=>customerName(data,r.customerId)},{key:'date',label:'Date'},{key:'description',label:'Description'},{key:'method',label:'Method'},{key:'amount',label:'Amount',render:r=>money(r.amount)},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></>}{kind==='utilization'&&<><Panel title="Self-Storage occupancy by size" subtitle="Current snapshot · Occupancy counts occupied units; maintenance and unavailable units remain in the total."><div className="grid gap-7 md:grid-cols-3">{['Small','Medium','Large'].map(size=>{const units=data.units.filter(r=>r.size===size);return <Meter key={size} label={`${size} units`} used={units.filter(r=>r.status==='OCCUPIED').length} max={units.length} unit="units"/>;})}</div></Panel><div className="grid gap-6 lg:grid-cols-2"><Panel title="Managed Inventory physical utilization"><Meter label="Active shelf volume in use" used={c.used} max={c.max}/></Panel><Panel title="Managed Inventory allocation utilization"><Meter label="Capacity allocated to rentals" used={c.allocated} max={c.max}/></Panel></div><Panel title="Shelf utilization" subtitle="Maintenance shelves are excluded from operational capacity totals."><Table rows={data.shelves} columns={[{key:'code',label:'Shelf'},{key:'max_volume_m3',label:'Max volume (m³)'},{key:'used_volume_m3',label:'Used volume (m³)'},{key:'remaining',label:'Remaining (m³)',render:r=>r.max_volume_m3-r.used_volume_m3},{key:'weight',label:'Weight (kg)',render:r=>`${r.used_weight_kg} / ${r.max_weight_kg}`},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel></>}{kind==='rentals'&&<><Panel title="Rental lifecycle"><Table rows={rentals} columns={[{key:'id',label:'Rental ID'},{key:'customer',label:'Customer',render:r=>customerName(data,r.customerId)},{key:'service',label:'Service',render:r=>r.service.replaceAll('_',' ')},{key:'resource',label:'Unit / capacity',render:r=>r.service==='SELF_STORAGE'?unitCode(data,r.unitId):`${r.allocated_capacity_m3} m³`},{key:'start',label:'Start'},{key:'end',label:'End'},{key:'status',label:'Status',render:r=><Status value={r.status}/>} ]}/></Panel><div className="grid gap-6 lg:grid-cols-2">{rentals.map(r=><Panel key={r.id} title={r.id} subtitle={customerName(data,r.customerId)}><Timeline entries={r.timeline}/></Panel>)}</div><Panel title="Customer activity" subtitle="Activity within the filtered rentals and reporting period."><Table rows={data.customers.filter(r=>rentals.some(x=>x.customerId===r.id))} columns={[{key:'name',label:'Customer'},{key:'rentals',label:'Rentals in period',render:r=>rentals.filter(x=>x.customerId===r.id).length},{key:'active',label:'Active rentals',render:r=>rentals.filter(x=>x.customerId===r.id&&x.status==='ACTIVE').length},{key:'payments',label:'Payments in period',render:r=>data.payments.filter(p=>p.customerId===r.id&&(!from||p.date>=from)&&(!to||p.date<=to)).length},{key:'support',label:'Support tickets',render:r=>data.support.filter(s=>s.customerId===r.id).length},{key:'verification',label:'Verification',render:r=><Status value={r.verification}/>} ]}/></Panel></>}</Screen>;}
'''
files['src/routes/ManagerRoutes.jsx']=r'''import {Navigate,Route,Routes} from 'react-router-dom';
import ManagerLayout from '@/layouts/ManagerLayout';
import DashboardPage from '@/pages/manager/DashboardPage';
import ReservationsPage from '@/pages/manager/ReservationsPage';
import CustomersPage from '@/pages/manager/CustomersPage';
import StorageUnitsPage from '@/pages/manager/StorageUnitsPage';
import StorageLocationsPage from '@/pages/manager/StorageLocationsPage';
import OperationsPage from '@/pages/manager/OperationsPage';
import ExtensionsPage from '@/pages/manager/ExtensionsPage';
import ServiceDeskPage from '@/pages/manager/ServiceDeskPage';
import FinancePage from '@/pages/manager/FinancePage';
import ReportsPage from '@/pages/manager/ReportsPage';
import {Screen,NotFound} from '@/components/manager/ManagerUI';
export default function ManagerRoutes(){return <Routes><Route element={<ManagerLayout/>}><Route index element={<Navigate to="dashboard" replace/>}/><Route path="dashboard" element={<DashboardPage/>}/><Route path="reservations" element={<ReservationsPage/>}/><Route path="reservations/:id" element={<ReservationsPage/>}/><Route path="customers" element={<CustomersPage/>}/><Route path="customers/:id" element={<CustomersPage/>}/><Route path="storage-units" element={<StorageUnitsPage/>}/><Route path="storage-units/:id" element={<StorageUnitsPage/>}/><Route path="storage-locations" element={<StorageLocationsPage/>}/><Route path="storage-locations/zones/:id" element={<StorageLocationsPage level="zones"/>}/><Route path="storage-locations/racks/:id" element={<StorageLocationsPage level="racks"/>}/><Route path="storage-locations/shelves/:id" element={<StorageLocationsPage level="shelves"/>}/><Route path="operations" element={<OperationsPage/>}/><Route path="operations/:id" element={<OperationsPage/>}/><Route path="tasks" element={<OperationsPage assignment/>}/><Route path="extensions" element={<ExtensionsPage/>}/><Route path="maintenance" element={<ServiceDeskPage kind="maintenance"/>}/><Route path="maintenance/:id" element={<ServiceDeskPage kind="maintenance"/>}/><Route path="support" element={<ServiceDeskPage kind="support"/>}/><Route path="support/:id" element={<ServiceDeskPage kind="support"/>}/><Route path="refunds" element={<FinancePage kind="refunds"/>}/><Route path="refunds/:id" element={<FinancePage kind="refunds"/>}/><Route path="charges" element={<FinancePage kind="charges"/>}/><Route path="reports/revenue" element={<ReportsPage key="revenue" kind="revenue"/>}/><Route path="reports/utilization" element={<ReportsPage key="utilization" kind="utilization"/>}/><Route path="reports/rentals" element={<ReportsPage key="rentals" kind="rentals"/>}/><Route path="*" element={<Screen title="Manager page unavailable"><NotFound/></Screen>}/></Route></Routes>;}
'''
for name,content in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
p=Path('src/routes/AppRoutes.jsx');s=p.read_text(encoding='utf-8-sig');s="import {lazy, Suspense} from 'react';\n"+s;s=s.replace('export default function AppRoutes()',"const ManagerRoutes = lazy(() => import('@/routes/ManagerRoutes'));\nexport default function AppRoutes()");s=s.replace('      <Route path="*" element={<Navigate to="/" replace />} />','      <Route path="/manager/*" element={<Suspense fallback={<div className="p-8 text-[#176B3A]" role="status">Loading facility workspace…</div>}><ManagerRoutes /></Suspense>} />\n      <Route path="*" element={<Navigate to="/" replace />} />');p.write_text(s,encoding='utf-8')
